-- Fixture-only integration test. Run with BEGIN / ROLLBACK.
do $$
declare owner_id uuid:=gen_random_uuid();customer_id uuid:=gen_random_uuid();other_id uuid:=gen_random_uuid();root uuid:=gen_random_uuid();small uuid:=gen_random_uuid();large uuid:=gen_random_uuid();station bigint;table_id bigint;data jsonb;options jsonb;o jsonb;guest jsonb;original_order bigint;split jsonb;blocked boolean;pickup_id bigint;
begin
 insert into auth.users(id,email,raw_user_meta_data) values(owner_id,owner_id||'@example.invalid','{"role":"negocio","business_name":"Variations QA"}'),(customer_id,customer_id||'@example.invalid','{}'),(other_id,other_id||'@example.invalid','{"role":"negocio","business_name":"Other"}');
 insert into public.menu_categories(restaurant_id,name) values(owner_id,'Bebidas');
 insert into public.kitchen_stations(restaurant_id,name) values(owner_id,'Barra') returning id into station;
 insert into public.restaurant_tables(restaurant_id,name) values(owner_id,'QA') returning id into table_id;
 update public.profiles set open_time=null,close_time=null,accepting_orders=true,guest_pickup_enabled=true,payment_cash=true,delivery_enabled=true,latitude=19.4,longitude=-99.1,delivery_radius_km=5,delivery_minimum=0,delivery_base_fee=10,delivery_fee_per_km=2 where id=owner_id;
 data:=jsonb_build_object('name','Café','price',20,'category','Bebidas','kitchen_station_id',station);
 options:=jsonb_build_array(jsonb_build_object('id',small,'name','Chico','price',25,'is_available',true),jsonb_build_object('id',large,'name','Grande','price',40,'is_available',true));
 perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_menu_product(root,data,options);perform public.save_menu_product(root,data,options);
 assert (select count(*)=3 from public.products where restaurant_id=owner_id),'Idempotent save duplicated variations';
 assert not public.product_is_sellable(root) and public.product_is_sellable(small),'Must require variation selection';
 assert (select name='Café · Grande' and kitchen_station_id=station and category='Bebidas' from public.products where id=large),'Variation metadata missing';
 perform public.open_cash_shift(owner_id,0);
 blocked:=false;begin perform public.create_pos_table_order(owner_id,jsonb_build_array(jsonb_build_object('id',root,'qty',1)),null,'dine_in',table_id,'cash',null,'QA');exception when raise_exception then blocked:=true;end;assert blocked,'POS ordered parent without a variation';
 o:=public.create_pos_table_order(owner_id,jsonb_build_array(jsonb_build_object('id',small,'qty',2,'price',.01),jsonb_build_object('id',large,'qty',1,'price',.01)),null,'dine_in',table_id,'cash',null,'QA');original_order:=(o->>'id')::bigint;
 assert (o->>'total')::numeric=90,'Client tampered with variation price';
 assert o->'items'->0->>'nombre'='Café · Chico','Variation lost from account';
 split:=public.record_cash_operation_once(gen_random_uuid(),'split_order',jsonb_build_object('p_order_id',original_order,'p_expected_items',o->'items','p_groups',jsonb_build_array(jsonb_build_array(jsonb_build_object('id',large,'qty',1)))));
 execute 'reset role';
 assert (select total=40 and items->0->>'nombre'='Café · Grande' from public.orders where id=(split->'new_order_ids'->>0)::bigint),'Split mixed variations';
 assert exists(select 1 from public.kitchen_tickets t cross join lateral jsonb_array_elements(t.items) i where t.order_id=original_order and i->>'nombre'='Café · Grande' and (i->>'station_id')::bigint=station),'Kitchen lost selection or station';
 execute 'set local role authenticated';
 blocked:=false;begin perform public.save_menu_product(root,data,options||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'name','  chico  ','price',30)));exception when raise_exception then blocked:=true;end;assert blocked,'Duplicate variation names accepted';
 assert (select count(*)=2 from public.products where parent_product_id=root and not is_archived),'Failed save changed options';
 perform set_config('request.jwt.claim.sub',other_id::text,true);
 blocked:=false;begin perform public.save_menu_product(root,data,'[]');exception when raise_exception then blocked:=true;end;assert blocked,'Another owner edited product';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 update public.products set is_available=false where id=small;
 assert not public.product_is_sellable(small) and public.product_is_sellable(large),'Per-variation availability broken';
 update public.products set is_available=false where id=root;
 assert not public.product_is_sellable(large),'Parent stock did not block variants';
 update public.products set is_available=true where id=root;
 assert public.product_is_sellable(large) and not public.product_is_sellable(small),'Parent toggle reset individual stock';
 o:=public.create_pos_table_order(owner_id,jsonb_build_array(jsonb_build_object('id',large,'qty',1)),null,'pickup',null,'cash',null,'Ana QA');pickup_id:=(o->>'id')::bigint;
 perform set_config('request.jwt.claim.sub',customer_id::text,true);
 o:=public.create_customer_order_once(gen_random_uuid(),jsonb_build_object('restaurant_id',owner_id,'items',jsonb_build_array(jsonb_build_object('id',large,'qty',1,'price',1)),'notes',null,'service_type','pickup','payment_method','cash','pickup_name','QA'));
 assert (o->>'total')::numeric=40,'Customer pickup variation price wrong';
 o:=public.create_delivery_order(owner_id,jsonb_build_array(jsonb_build_object('id',large,'qty',1,'price',1)),null,'cash','Dirección QA 123',null,19.4,-99.1,'Ana QA','5512345678',null);
 assert (o->>'subtotal')::numeric=40,'Delivery variation price wrong';
 execute 'reset role';execute 'set local role service_role';
 guest:=public.create_guest_pickup_order(encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'),encode(extensions.digest(gen_random_uuid()::text,'sha256'),'hex'),owner_id,jsonb_build_array(jsonb_build_object('id',large,'qty',1,'price',1)),'Ana QA','cash',null);
 assert (guest->>'total')::numeric=40,'QR guest variation price wrong';
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',owner_id::text,true);
 -- Editing and retirement must not rewrite previous order snapshots.
 perform public.save_menu_product(root,data||'{"name":"Café nuevo"}',jsonb_build_array(jsonb_build_object('id',large,'name','Extra grande','price',55,'is_available',true)));
 assert (select is_archived from public.products where id=small),'Removed variant was not retired';
 perform public.register_pos_payment_v2(pickup_id,'cash',40,0,40);
 execute 'reset role';
 assert exists(select 1 from public.kitchen_tickets t cross join lateral jsonb_array_elements(t.items) i where t.order_id=pickup_id and i->>'nombre'='Café · Grande' and (i->>'price')::numeric=40),'Pending pickup lost its original variation after an edit';
 execute 'set local role authenticated';
 execute 'reset role';
 assert exists(select 1 from public.orders o cross join lateral jsonb_array_elements(o.items) i where o.id=original_order and i->>'nombre'='Café · Chico' and (i->>'price')::numeric=25),'Historical items changed';
 execute 'set local role anon';
 assert exists(select 1 from public.public_qr_products where id=large and variation_name='Extra grande'),'QR catalog missing variation';
 assert not exists(select 1 from public.public_qr_products where id=small),'QR exposes retired variation';
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',owner_id::text,true);
 perform public.archive_menu_product(root);
 assert not public.product_is_sellable(large),'Archived root is still sellable';
 execute 'reset role';assert (select count(*)=3 from public.products where restaurant_id=owner_id),'Archive deleted historical product IDs';
end;$$;
